  end

  PVS <-->|viewType + creationParams| PVR
  PVR <-->|创建/销毁| PVF
  Compositor <-->|纹理/层合成| NV
```

---

## Android：三种合成模式对比

| 模式                         | 原理                               | 性能             | 支持触摸 | 支持无障碍 | 推荐程度     |
| ---------------------------- | ---------------------------------- | ---------------- | -------- | ---------- | ------------ |
| **Virtual Display（VD）**    | 渲染到独立虚拟显示器，通过纹理合成 | 好（旧默认）     | 有限制   | 差         | 不推荐       |
| **Hybrid Composition（HC）** | 原生视图直接嵌入 View 层级         | 差（额外帧开销） | 完整     | 完整       | 旧设备兼容用 |
| **Texture Layer HC（TLHC）** | HC 变种，通过硬件纹理提升性能      | 最好（3.x 默认） | 完整     | 完整       | 推荐         |

Flutter 3.x 在 Android 上默认使用 TLHC 模式。可通过以下代码强制指定模式：

```dart
AndroidView(
  viewType: 'com.example/map_view',
  creationParams: {'apiKey': mapApiKey},
  creationParamsCodec: const StandardMessageCodec(),
  // 强制指定 Hybrid Composition
  gestureRecognizers: const {},
  onPlatformViewCreated: (id) => _onViewCreated(id),
)
```

---

## 实现自定义 Platform View

以「自定义原生签名板」为例，演示完整实现流程。

### Flutter 侧

```dart
// signature_view.dart
class SignatureView extends StatefulWidget {
  final Function(Uint8List) onSigned;

  const SignatureView({required this.onSigned, super.key});

  @override
  State<SignatureView> createState() => _SignatureViewState();
}

class _SignatureViewState extends State<SignatureView> {
  static const _viewType = 'com.example/signature_view';
  late MethodChannel _channel;

  @override
  Widget build(BuildContext context) {
    if (defaultTargetPlatform == TargetPlatform.android) {
      return AndroidView(
        viewType: _viewType,
        onPlatformViewCreated: _onViewCreated,
        gestureRecognizers: {
          Factory<EagerGestureRecognizer>(EagerGestureRecognizer.new),
        },
      );
    } else if (defaultTargetPlatform == TargetPlatform.iOS) {
      return UiKitView(
        viewType: _viewType,
        onPlatformViewCreated: _onViewCreated,
        gestureRecognizers: {
          Factory<EagerGestureRecognizer>(EagerGestureRecognizer.new),
        },
      );
    }
    return const Placeholder();
  }

  void _onViewCreated(int viewId) {
    _channel = MethodChannel('${_viewType}_$viewId');
  }

  Future<Uint8List?> captureSignature() async {
    final bytes = await _channel.invokeMethod<Uint8List>('capture');
    return bytes;
  }

  Future<void> clearSignature() async {
    await _channel.invokeMethod<void>('clear');
  }
}
```

### Android 侧（Kotlin）

```kotlin
// SignatureViewFactory.kt
class SignatureViewFactory(
  private val messenger: BinaryMessenger
) : PlatformViewFactory(StandardMessageCodec.INSTANCE) {

  override fun create(context: Context, viewId: Int, args: Any?): PlatformView {
    return SignaturePlatformView(context, messenger, viewId)
  }
}

class SignaturePlatformView(
  context: Context,
  messenger: BinaryMessenger,
  viewId: Int
) : PlatformView, MethodCallHandler {

  private val signatureView = NativeSignatureView(context)
  private val channel = MethodChannel(
    messenger,
    "com.example/signature_view_$viewId"
  )

  init {
    channel.setMethodCallHandler(this)
  }

  override fun getView(): View = signatureView

  override fun onMethodCall(call: MethodCall, result: Result) {
    when (call.method) {
      "capture" -> {
        val bitmap = signatureView.exportToBitmap()
        val stream = ByteArrayOutputStream()
        bitmap.compress(Bitmap.CompressFormat.PNG, 100, stream)
        result.success(stream.toByteArray())
      }
      "clear" -> {
        signatureView.clear()
        result.success(null)
      }
      else -> result.notImplemented()
    }
  }

  override fun dispose() {
    channel.setMethodCallHandler(null)
  }
}
```

注册工厂（在 Plugin 或 MainActivity 中）：

```kotlin
class MainActivity : FlutterActivity() {
  override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
    super.configureFlutterEngine(flutterEngine)
    flutterEngine.platformViewsController.registry.registerViewFactory(
      "com.example/signature_view",
      SignatureViewFactory(flutterEngine.dartExecutor.binaryMessenger)
    )
  }
}
```

### iOS 侧（Swift）

```swift
// SignatureViewFactory.swift
class SignatureViewFactory: NSObject, FlutterPlatformViewFactory {
  private let messenger: FlutterBinaryMessenger

  init(messenger: FlutterBinaryMessenger) {
    self.messenger = messenger
  }

  func create(
    withFrame frame: CGRect,
    viewIdentifier viewId: Int64,
    arguments args: Any?
  ) -> FlutterPlatformView {
    return SignaturePlatformView(
      frame: frame,
      viewId: viewId,
      messenger: messenger
    )
  }
}

class SignaturePlatformView: NSObject, FlutterPlatformView {
  private let signatureView: NativeSignatureView
  private let channel: FlutterMethodChannel

  init(frame: CGRect, viewId: Int64, messenger: FlutterBinaryMessenger) {
    signatureView = NativeSignatureView(frame: frame)
    channel = FlutterMethodChannel(
      name: "com.example/signature_view_\(viewId)",
      binaryMessenger: messenger
    )
    super.init()

    channel.setMethodCallHandler { [weak self] call, result in
      guard let self = self else { return }
      switch call.method {
      case "capture":
        result(self.signatureView.exportToPNG())
      case "clear":
        self.signatureView.clear()
        result(nil)
      default:
        result(FlutterMethodNotImplemented)
      }
    }
  }

  func view() -> UIView { signatureView }
}
```

